import{_ as t,c as a,o as s,ag as n}from"./chunks/framework.CoPVQkzc.js";const m=JSON.parse('{"title":"Velocity Variable Replacement","description":"Template variable syntax and usage","frontmatter":{"title":"Velocity Variable Replacement","description":"Template variable syntax and usage"},"headers":[],"relativePath":"engine/velocity_variable_replacement.md","filePath":"engine/velocity_variable_replacement.md","lastUpdated":1788476353000}'),o={name:"engine/velocity_variable_replacement.md"};function r(i,e,d,l,c,p){return s(),a("div",null,e[0]||(e[0]=[n('<h1 id="velocity-variable-replacement" tabindex="-1">Velocity Variable Replacement <a class="header-anchor" href="#velocity-variable-replacement" aria-label="Permalink to &quot;Velocity Variable Replacement&quot;">​</a></h1><p>OIE uses <strong>Apache Velocity</strong> syntax for variable substitution in connector templates, file names, directory paths, and other text fields throughout the channel editor. This is distinct from JavaScript and provides a lightweight way to insert dynamic values.</p><h2 id="basic-syntax" tabindex="-1">Basic syntax <a class="header-anchor" href="#basic-syntax" aria-label="Permalink to &quot;Basic syntax&quot;">​</a></h2><p>Variables stored in maps are referenced using the <code>${}</code> syntax:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>${variableName}</span></span></code></pre></div><p>This pulls the value from the variable maps (see <a href="#variable-map-priority">Variable Map Priority</a> below).</p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><p><strong>In a File Writer filename:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>message_${message.messageId}_${date.get(&#39;yyyyMMdd&#39;)}.hl7</span></span></code></pre></div><p><strong>In an HTTP Sender URL:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.example.com/patients/${patientId}/records</span></span></code></pre></div><p><strong>In a destination template:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Patient: ${patientLastName}, ${patientFirstName}</span></span>\n<span class="line"><span>MRN: ${medicalRecordNumber}</span></span></code></pre></div><h2 id="conditional-statements" tabindex="-1">Conditional statements <a class="header-anchor" href="#conditional-statements" aria-label="Permalink to &quot;Conditional statements&quot;">​</a></h2><p>Velocity supports <code>#if</code> / <code>#else</code> / <code>#elseif</code> / <code>#end</code> for conditional logic within templates:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#if(${gender} == &quot;M&quot;)</span></span>\n<span class="line"><span>Male</span></span>\n<span class="line"><span>#elseif(${gender} == &quot;F&quot;)</span></span>\n<span class="line"><span>Female</span></span>\n<span class="line"><span>#else</span></span>\n<span class="line"><span>Unknown</span></span>\n<span class="line"><span>#end</span></span></code></pre></div><p>This is useful when the output format varies based on message content without needing a full JavaScript transformer step.</p><h2 id="for-loops" tabindex="-1">For loops <a class="header-anchor" href="#for-loops" aria-label="Permalink to &quot;For loops&quot;">​</a></h2><p>Velocity supports <code>#foreach</code> loops for iterating over collections:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#foreach($item in ${itemList})</span></span>\n<span class="line"><span>Item: ${item}</span></span>\n<span class="line"><span>#end</span></span></code></pre></div><h2 id="variable-map-priority" tabindex="-1">Variable map priority <a class="header-anchor" href="#variable-map-priority" aria-label="Permalink to &quot;Variable map priority&quot;">​</a></h2><p>When you reference <code>${variableName}</code>, OIE loads all variable maps into a single Velocity context. Maps loaded later overwrite earlier values for the same key, so later maps have higher priority. The effective priority from highest to lowest is:</p><ol><li><strong>Response Map</strong> - Destination response data</li><li><strong>Connector Map</strong> - Variables scoped to the current connector</li><li><strong>Channel Map</strong> - Variables scoped to the current message across all connectors</li><li><strong>Source Map</strong> - Variables populated by the source connector (e.g., remote address, original filename)</li><li><strong>Global Channel Map</strong> - Variables shared across all messages in this channel</li><li><strong>Global Map</strong> - Variables shared across all channels</li><li><strong>Configuration Map</strong> - Server-wide key-value pairs from Settings</li></ol><p>If no match is found, the literal string <code>${variableName}</code> is output.</p><h2 id="standard-variables-and-templates" tabindex="-1">Standard variables and templates <a class="header-anchor" href="#standard-variables-and-templates" aria-label="Permalink to &quot;Standard variables and templates&quot;">​</a></h2><p>Several built-in variables are always available in Velocity templates:</p><h3 id="message-properties" tabindex="-1">Message properties <a class="header-anchor" href="#message-properties" aria-label="Permalink to &quot;Message properties&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>${message.messageId}</code></td><td>The current message ID</td></tr><tr><td><code>${message.encodedData}</code></td><td>The encoded (outbound) message content</td></tr><tr><td><code>${message.rawData}</code></td><td>The raw inbound message content</td></tr><tr><td><code>${message.transformedData}</code></td><td>The transformed message content</td></tr><tr><td><code>${message.channelId}</code></td><td>The channel ID for this message</td></tr><tr><td><code>${message.channelName}</code></td><td>The channel name for this message</td></tr><tr><td><code>${message.connectorName}</code></td><td>The name of the current connector</td></tr><tr><td><code>${message.metaDataId}</code></td><td>The metadata ID of the current connector</td></tr><tr><td><code>${channelId}</code></td><td>The current channel&#39;s UUID</td></tr><tr><td><code>${channelName}</code></td><td>The current channel&#39;s name</td></tr></tbody></table><h3 id="utility-variables" tabindex="-1">Utility variables <a class="header-anchor" href="#utility-variables" aria-label="Permalink to &quot;Utility variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>${date.get(&#39;yyyyMMdd&#39;)}</code></td><td>Current date/time formatted with a Java <code>SimpleDateFormat</code> pattern</td></tr><tr><td><code>${DATE}</code></td><td>Current timestamp formatted as <code>dd-MM-yy_HH-mm-ss.SS</code></td></tr><tr><td><code>${COUNT}</code></td><td>Auto-incrementing counter (increments each time it is referenced)</td></tr><tr><td><code>${UUID}</code></td><td>A random UUID string</td></tr><tr><td><code>${SYSTIME}</code></td><td>Current system time in milliseconds</td></tr><tr><td><code>${HASH}</code></td><td>SHA-256 hash of the encoded message content (falls back to raw if encoded is unavailable)</td></tr><tr><td><code>${originalFilename}</code></td><td>Original filename from the source connector (defaults to <code>&lt;timestamp&gt;.dat</code> if unset)</td></tr></tbody></table><h3 id="date-formatting-examples" tabindex="-1">Date formatting examples <a class="header-anchor" href="#date-formatting-examples" aria-label="Permalink to &quot;Date formatting examples&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>${date.get(&#39;yyyyMMdd&#39;)}          → 20240101</span></span>\n<span class="line"><span>${date.get(&#39;yyyy-MM-dd HH:mm&#39;)} → 2024-01-01 12:00</span></span>\n<span class="line"><span>${date.get(&#39;yyyyMMddHHmmss&#39;)}   → 20240101120000</span></span></code></pre></div><h2 id="where-velocity-is-used" tabindex="-1">Where Velocity is used <a class="header-anchor" href="#where-velocity-is-used" aria-label="Permalink to &quot;Where Velocity is used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Example</th></tr></thead><tbody><tr><td><strong>Destination templates</strong></td><td>Message body content</td></tr><tr><td><strong>File Writer directory/filename</strong></td><td><code>/output/${channelName}/${date.get(&#39;yyyyMMdd&#39;)}/</code></td></tr><tr><td><strong>HTTP Sender URL</strong></td><td><code>https://host/api/${patientId}</code></td></tr><tr><td><strong>HTTP headers/parameters</strong></td><td>Header values with dynamic content</td></tr><tr><td><strong>Email subject/body</strong></td><td>SMTP sender fields</td></tr><tr><td><strong>Database Writer SQL</strong></td><td>Parameterized INSERT statements</td></tr><tr><td><strong>Alert templates</strong></td><td>Alert notification content</td></tr></tbody></table><h2 id="velocity-vs-javascript" tabindex="-1">Velocity vs. JavaScript <a class="header-anchor" href="#velocity-vs-javascript" aria-label="Permalink to &quot;Velocity vs. JavaScript&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Velocity <code>${}</code></th><th>JavaScript</th></tr></thead><tbody><tr><td><strong>Use case</strong></td><td>Simple variable insertion in templates</td><td>Complex logic and transformations</td></tr><tr><td><strong>Syntax</strong></td><td><code>${varName}</code></td><td><code>channelMap.get(&#39;varName&#39;)</code></td></tr><tr><td><strong>Where</strong></td><td>Template fields, filenames, URLs</td><td>Transformer/filter steps, scripts</td></tr><tr><td><strong>Conditionals</strong></td><td><code>#if/#else/#end</code></td><td><code>if/else</code></td></tr><tr><td><strong>Loops</strong></td><td><code>#foreach</code></td><td><code>for</code>, <code>while</code></td></tr><tr><td><strong>Power</strong></td><td>Lightweight substitution</td><td>Full programming language</td></tr></tbody></table><p>Use Velocity for simple value insertion. Use JavaScript transformer steps for complex logic, calculations, and external lookups.</p>',37)]))}const g=t(o,[["render",r]]);export{m as __pageData,g as default};
